145	/** Update the customer's display name. */
146	export async function updateProfileName(
147	  name: string,
148	): Promise<{ ok: boolean; error?: string }> {
149	  const profile = await requireRole("customer");
150	  const trimmed = name.trim();
151	  if (trimmed.length < 1 || trimmed.length > 120) {
152	    return { ok: false, error: "Enter your name." };
153	  }
154	  const supabase = await createClient();
155	  const { error } = await supabase
156	    .from("profiles")
157	    .update({ full_name: trimmed })
158	    .eq("id", profile.id);
159	  if (error) return { ok: false, error: "Could not save your name." };
160	  revalidatePath("/account/settings");
161	  return { ok: true };
162	}
