94	/**
95	 * End the mock call. The client's count-up timer is the source of truth for
96	 * elapsed seconds (mock mode). Computes the final accounting (block + overage +
97	 * commission), captures the hold, and marks the session + booking completed.
98	 * Idempotent: a session already completed is left as-is.
99	 */
100	export async function endSession(
101	  bookingId: string,
102	  elapsedSeconds: number,
103	): Promise<EndSessionResult> {
104	  const booking = await loadBookingForParty(bookingId);
105	  if (!booking) return { error: "This session isn't available." };
106	
107	  const supabase = await createClient();
108	  const { data: session } = await supabase
109	    .from("sessions")
110	    .select("*")
111	    .eq("booking_id", bookingId)
112	    .maybeSingle();
113	  if (!session) return { error: "This session isn't available." };
114	  if (session.status === "completed") return { ok: true };
115	
116	  const elapsed = Math.max(0, Math.floor(elapsedSeconds || 0));
117	  const accounting = computeSessionAccounting({
118	    priceBlockCents: booking.price_block_cents,
119	    overagePerMinCents: booking.overage_per_min_cents,
120	    elapsedSeconds: elapsed,
121	    blockMinutes: booking.block_minutes as BlockMinutes,
122	  });
123	
124	  const calls = getCalls();
125	  if (session.call_session_ref) {
126	    await calls.endSession({ callSessionRef: session.call_session_ref });
127	  }
128	
129	  const payments = getPayments();
130	  if (booking.payment_ref) {
131	    await payments.capture({
132	      paymentRef: booking.payment_ref,
133	      amountCents: accounting.totalCents,
134	    });
135	  }
136	
137	  const admin = createAdminClient();
138	  const { error } = await admin
139	    .from("sessions")
140	    .update({
141	      ended_at: new Date().toISOString(),
142	      elapsed_seconds: elapsed,
143	      overage_minutes: accounting.overageMinutes,
144	      total_price_cents: accounting.totalCents,
145	      commission_cents: accounting.commissionCents,
146	      provider_earnings_cents: accounting.providerEarningsCents,
147	      status: "completed",
148	    })
149	    .eq("id", session.id);
150	  if (error) return { error: "We couldn't finish the call." };
151	
152	  await supabase
153	    .from("bookings")
154	    .update({ status: "completed" })
155	    .eq("id", bookingId);
156	
157	  return { ok: true };
158	}
