22	export function UpcomingBookings({ items }: { items: UpcomingItem[] }) {
23	  const [pending, startTransition] = useTransition();
24	  const [rescheduleId, setRescheduleId] = React.useState<string | null>(null);
25	  const [newTime, setNewTime] = React.useState("");
26	  const { announce, toast } = useToast();
27	
28	  function cancel(id: string) {
29	    startTransition(async () => {
30	      const res = await cancelBooking(id);
31	      if (!res.ok) {
32	        toast(res.error ?? t("booking.error"), "alert");
33	        return;
34	      }
35	      announce(
36	        res.released ? t("account.cancelledRefund") : t("account.cancelledCharged"),
37	        true,
38	      );
39	    });
40	  }
41	
42	  function saveReschedule(id: string) {
43	    if (!newTime) return;
44	    startTransition(async () => {
45	      const res = await rescheduleBooking({
46	        bookingId: id,
47	        scheduledAt: new Date(newTime).toISOString(),
